namespace ghidra.program.model.symbol;


/**
 * Class to define reference types for data.
 */
public sealed class DataRefType : RefType {
	
	// memory access type
	protected static readonly int READX    =  1;
	protected static readonly int WRITEX   =  2;
	protected static readonly int INDX     =  4;

	private int      access = 0;
	
	/**
	 * Constructs a DataRefType with the given type.
	 */
    protected DataRefType(byte type, string name, int access) : base(type, name)
    {
        this.access = access;
	}
	
    /* @Override */
	public bool isData() {
		return true;
	}
	
	/* @Override */
	public bool isRead() {
		return (access & READX) == READX;
	}

	/* @Override */	
	public bool isWrite() {
		return (access & WRITEX) == WRITEX;
	}
	
	/* @Override */
	public bool isIndirect() {
		return (access & INDX) == INDX;
	}
	
}
